    if (body_vectors == NULL || predicted_body_vectors == NULL || weights == NULL || rms_rad == NULL) {
        *rms_rad = 0.0;
        return ADCS_E_NULL;
    }

    if (count < 1 || count > 32) {
        *rms_rad = 0.0;
        return ADCS_E_RANGE;
    }

    for (size_t i = 0; i < count; i++) {
        if (!isfinite(weights[i]) || weights[i] <= 0.0) {
            *rms_rad = 0.0;
            return ADCS_E_RANGE;
        }
    }

    double sum_w_theta_sq = 0.0;
    double sum_w = 0.0;

    for (size_t i = 0; i < count; i++) {
        adcs_vec3_t b_norm, p_norm;

        if (adcs_vec3_normalize(&body_vectors[i], ADCS_EPS_NORM, &b_norm) != ADCS_OK) {
            *rms_rad = 0.0;
            return ADCS_E_RANGE;
        }
        if (adcs_vec3_normalize(&predicted_body_vectors[i], ADCS_EPS_NORM, &p_norm) != ADCS_OK) {
            *rms_rad = 0.0;
            return ADCS_E_RANGE;
        }

        double dot = adcs_vec3_dot(&b_norm, &p_norm);
        double clamped_dot = ADCS_CLAMP(dot, -1.0, 1.0);
        double theta = acos(clamped_dot);

        sum_w_theta_sq += weights[i] * theta * theta;
        sum_w += weights[i];
    }

    if (sum_w <= 0.0) {
        *rms_rad = 0.0;
        return ADCS_E_RANGE;
    }

    *rms_rad = sqrt(sum_w_theta_sq / sum_w);
    return ADCS_OK;
}

