candidates.raw:
    if ((body_vectors == NULL) || (predicted_body_vectors == NULL) || (weights == NULL) || (rms_rad == NULL)) {
        *rms_rad = 0.0;
        return ADCS_E_NULL;
    }
    if ((count < 1U) || (count > 32U)) {
        *rms_rad = 0.0;
        return ADCS_E_RANGE;
    }

    double sum_w = 0.0;
    double sum_w_theta_sq = 0.0;
    size_t k;

    for (k = 0; k < count; k++) {
        if ((!isfinite(weights[k])) || (weights[k] <= 0.0)) {
            *rms_rad = 0.0;
            return ADCS_E_RANGE;
        }
        if (!adcs_is_finite_vec3(&body_vectors[k]) || !adcs_is_finite_vec3(&predicted_body_vectors[k])) {
            *rms_rad = 0.0;
            return ADCS_E_RANGE;
        }

        double norm_b = adcs_vec3_norm(&body_vectors[k]);
        double norm_p = adcs_vec3_norm(&predicted_body_vectors[k]);

        if (norm_b <= ADCS_EPS_NORM || norm_p <= ADCS_EPS_NORM) {
            *rms_rad = 0.0;
            return ADCS_E_RANGE;
        }

        double dot = (body_vectors[k].x * predicted_body_vectors[k].x +
                      body_vectors[k].y * predicted_body_vectors[k].y +
                      body_vectors[k].z * predicted_body_vectors[k].z) /
                     (norm_b * norm_p);

        if (dot < -1.0) dot = -1.0;
        else if (dot > 1.0) dot = 1.0;

        double theta = acos(dot);

        sum_w += weights[k];
        sum_w_theta_sq += weights[k] * theta * theta;
    }

    if (sum_w <= 0.0) {
        *rms_rad = 0.0;
        return ADCS_E_RANGE;
    }

    double rms_val = sqrt(sum_w_theta_sq / sum_w);

    if (!isfinite(rms_val)) {
        *rms_rad = 0.0;
        return ADCS_E_NOT_FINITE;
    }

    *rms_rad = rms_val;
    return ADCS_OK;
}

